#include <stdio.h>
int main() {
    int a = 27;
    int b = 25;
    printf("post_inc_a: %d\n", a++);
    printf("pre_inc_a: %d\n", ++a);
    printf("post_dec_b: %d\n", b--);
    printf("pre_dec_b: %d\n", --b);
    printf("combined: %d\n", a++ + ++b);
    printf("final_a: %d, final_b: %d\n", a, b);
    return 0;
}
